import{_ as t,o,c as i,ai as n}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Creating Custom Benchmark Suites","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/benchmark-builder.md","filePath":"en/guide/benchmark-builder.md"}'),r={name:"en/guide/benchmark-builder.md"};function a(s,e,l,u,c,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="creating-custom-benchmark-suites" tabindex="-1">Creating Custom Benchmark Suites <a class="header-anchor" href="#creating-custom-benchmark-suites" aria-label="Permalink to &quot;Creating Custom Benchmark Suites&quot;">​</a></h1><p>Create your own benchmark suites to test models on topics that matter to you — no JSON editing required. The Benchmark Suite Builder lets you craft questions manually or use a local AI model to generate them automatically.</p><p><strong>Sidebar item:</strong> Benchmark Builder <strong>Route:</strong> <code>/benchmark</code> (Builder tab)</p><h2 id="manual-question-entry" tabindex="-1">Manual Question Entry <a class="header-anchor" href="#manual-question-entry" aria-label="Permalink to &quot;Manual Question Entry&quot;">​</a></h2><p>To build a suite entirely by hand:</p><ol><li>Open the <strong>Benchmark</strong> page and click the <strong>Builder</strong> tab.</li><li>Enter a <strong>Suite name</strong> and an optional <strong>Description</strong>.</li><li>Click <strong>Add Question</strong> to create a new entry.</li><li>Fill in the <strong>question text</strong>.</li><li>Add the <strong>answer choices</strong> (A, B, C, D). You can add more choices if needed.</li><li>Select the <strong>correct answer</strong> from the dropdown.</li><li>Optionally assign a <strong>category</strong> to group questions by subject.</li><li>Repeat steps 3-7 for each question you want to add.</li><li>Click <strong>Save Suite</strong> when you are done.</li></ol><p>Your custom suite now appears alongside the built-in suites and is ready to run.</p><h2 id="ai-assisted-generation" tabindex="-1">AI-Assisted Generation <a class="header-anchor" href="#ai-assisted-generation" aria-label="Permalink to &quot;AI-Assisted Generation&quot;">​</a></h2><p>Let a local model do the heavy lifting:</p><ol><li>In the Builder tab, switch to the <strong>AI Generate</strong> section.</li><li>Enter a <strong>topic</strong> — for example, &quot;French Revolution&quot;, &quot;TCP/IP networking&quot;, or &quot;organic chemistry&quot;.</li><li>Choose the <strong>number of questions</strong> to generate.</li><li>Select a <strong>difficulty</strong> level (easy, medium, hard).</li><li>Pick the <strong>model</strong> that will generate the questions from the dropdown.</li><li>Click <strong>Generate</strong>. The model streams questions in real time.</li></ol><p>Once generation completes:</p><ul><li><strong>Review</strong> each question for accuracy.</li><li><strong>Edit</strong> any question text, choices, or correct answers that need fixing.</li><li><strong>Deselect</strong> questions that are poorly formed or incorrect — they will not be included.</li><li>Click <strong>Add to Suite</strong> to merge the approved questions into your suite.</li></ul><h2 id="editing-suites" tabindex="-1">Editing Suites <a class="header-anchor" href="#editing-suites" aria-label="Permalink to &quot;Editing Suites&quot;">​</a></h2><p>Click the <strong>Edit</strong> button on any custom suite to modify it. You can:</p><ul><li>Rename the suite or update its description</li><li>Add, remove, or reorder questions</li><li>Edit individual question text, choices, and correct answers</li><li>Change question categories</li></ul><p>Built-in suites (ARC, GSM8K, etc.) cannot be edited, but you can duplicate them to create a modified version.</p><h2 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h2><p>Click the <strong>Export</strong> button on a custom suite to download it as a <strong>JSON</strong> file. The exported file contains:</p><ul><li>Suite name and description</li><li>All questions with their choices, correct answer index, and category</li></ul><p>Share exported JSON files with others or contribute them to the <a href="/llmxray/docs/en/community/benchmarks.html">Community Benchmarks</a> collection.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Use specific topics</strong> — &quot;Mitochondrial electron transport chain&quot; generates better questions than &quot;biology&quot;. The more focused the topic, the more accurate the AI output.</li><li><strong>Mix manual and AI</strong> — Generate a batch with AI, then add a few hand-crafted edge-case questions to round out coverage.</li><li><strong>Always validate answers</strong> — AI-generated correct answers can be wrong. Double-check each one before saving.</li><li><strong>Larger models produce better questions</strong> — A 14B-parameter model generates significantly more accurate and nuanced questions than a 3B model. Use the best model you have available.</li><li><strong>Categorize consistently</strong> — Use consistent category names across questions so the results breakdown is meaningful.</li><li><strong>Start small</strong> — Generate 5-10 questions first to check quality before committing to a larger batch.</li></ul>',22)])])}const m=t(r,[["render",a]]);export{g as __pageData,m as default};
